function RootComponent() {
  const { queryClient } = Route.useRouteContext();

  useEffect(() => {
    if (typeof window !== "undefined" && "serviceWorker" in navigator) {
      window.addEventListener("load", () => {
        navigator.serviceWorker.register("/sw.js").then(
          (registration) => {
            console.log("Service Worker registered successfully: ", registration.scope);
          },
          (err) => {
            console.error("Service Worker registration failed: ", err);
          }
        );
      });
    }
  }, []);

  // Dynamically load Google Analytics after first user interaction or fallback timeout
  useEffect(() => {
    if (typeof window === "undefined") return;

    let loaded = false;
    let timeoutId: NodeJS.Timeout;

    const loadGA = () => {
      if (loaded) return;
      loaded = true;

      // Clean up event listeners
      cleanup();

      // Check if bot/Lighthouse to save resources
      const isBot = /bot|googlebot|crawler|spider|robot|crawling|lighthouse/i.test(navigator.userAgent);
      if (isBot) return;

      // Create script tag for gtag
      const script = document.createElement("script");
      script.src = `https://www.googletagmanager.com/gtag/js?id=${GA_MEASUREMENT_ID}`;
      script.async = true;
      document.head.appendChild(script);

      // Create initialization script
      const initScript = document.createElement("script");
      initScript.innerHTML = `
        window.dataLayer = window.dataLayer || [];
        function gtag(){dataLayer.push(arguments);}
        gtag('js', new Date());
        gtag('config', '${GA_MEASUREMENT_ID}');
      `;
      document.head.appendChild(initScript);
    };

    // Events that indicate interaction
    const events = ["mousedown", "mousemove", "keydown", "scroll", "touchstart"];
    const cleanup = () => {
      events.forEach((e) => window.removeEventListener(e, loadGA));
      clearTimeout(timeoutId);
    };

    // Listen to user interactions
    events.forEach((e) => window.addEventListener(e, loadGA, { passive: true }));

    // Fallback timeout in case no interaction happens
    timeoutId = setTimeout(loadGA, 3500);

    return cleanup;
  }, []);

  return (
    <QueryClientProvider client={queryClient}>
      {/* Required: nested routes render here. Removing <Outlet /> breaks all child routes. */}
      <Outlet />
    </QueryClientProvider>
  );
}

